def solve(inputs: dict) -> float:
    import re
    text = inputs.get('text') or inputs.get('problem') or ''
    if not text:
        for v in inputs.values():
            if isinstance(v, str):
                text = v
                break
    base = inputs.get('base'); exp = inputs.get('exp'); mod = inputs.get('mod')
    if base is None or exp is None or mod is None:
        nums = list(map(int, re.findall(r'\d+', text)))
        base, exp, mod = nums[0], nums[1], nums[2]
    return float(pow(int(base), int(exp), int(mod)))

